mapper.select:
SELECT a.ShiftID AS shiftId, a.OperatorID AS operatorId, a.StaDate AS staDate, a.TeamID AS teamId, SUM( CASE WHEN a.VehicleClass = 1 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS cust1, SUM( CASE WHEN a.VehicleClass = 2 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS cust2, SUM( CASE WHEN a.VehicleClass = 3 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS cust3, SUM( CASE WHEN a.VehicleClass = 4 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS cust4, SUM( CASE WHEN a.VehicleClass < 10 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS custSubTotal, SUM( CASE WHEN a.VehicleClass = 11 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truck1, SUM( CASE WHEN a.VehicleClass = 12 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truck2, SUM( CASE WHEN a.VehicleClass = 13 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truck3, SUM( CASE WHEN a.VehicleClass = 14 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truck4, SUM( CASE WHEN a.VehicleClass = 15 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truck5, SUM( CASE WHEN a.VehicleClass = 16 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truck6, SUM( CASE
WHEN a.VehicleClass > 10 AND a.VehicleClass < 20 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS truckSubTotal, SUM( CASE WHEN a.VehicleClass = 21 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS spec1, SUM( CASE WHEN a.VehicleClass = 22 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS spec2, SUM( CASE WHEN a.VehicleClass = 23 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS spec3, SUM( CASE WHEN a.VehicleClass = 24 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS spec4, SUM( CASE WHEN a.VehicleClass = 25 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS spec5, SUM( CASE WHEN a.VehicleClass = 26 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS spec6, SUM( CASE
WHEN a.VehicleClass > 20 AND a.VehicleClass < 30 AND a.CardType=26 THEN a.CardNum ELSE 0 END ) AS specSubTotal, IFNULL(SUM(CASE WHEN a.DealStatus&16777216=16777216 THEN a.CarNum ELSE 0 END ), 0) AS etcNum, IFNULL(SUM(CASE WHEN a.CardType = 254 AND a.DealStatus&14 != 14 THEN a.CarNum ELSE 0 END), 0) AS paperNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=8 AND a.DealStatus&2048 != 2048 AND a.DealStatus&32 != 32 THEN a.CarNum ELSE 0 END), 0) AS militaryNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=6 THEN a.CarNum ELSE 0 END), 0) AS officialNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=14 AND a.CardType != 254 THEN a.CarNum ELSE 0 END), 0) AS fleetNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=10 AND a.DealStatus&2048 != 2048 AND a.DealStatus&32 != 32 AND a.VehicleStatus IN (1,101) THEN a.CarNum ELSE 0 END), 0) AS preferNum, IFNULL(SUM(CASE WHEN a.DealStatus&32=32 THEN a.CarNum ELSE 0 END),0) AS noneNum, IFNULL(SUM(CASE WHEN a.DealStatus&2048=2048 AND a.CardType IN (0,2,26) THEN a.CarNum ELSE 0 END),0) AS badNum FROM tbstatexit a
AND RIGHT(OperatorID, 3) != 981 AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate = #{intTime}
AND ShiftID = #{shiftId}
GROUP BY OperatorID ORDER BY ShiftID ASC, OperatorID ASC

SELECT a.ShiftID AS shiftId, a.OperatorID AS operatorId, a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, LEFT(a.StaDate, 6) AS monthDate, a.StaDate AS staDate, SUM(CASE WHEN a.VehicleClass = 1 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS cust1, SUM(CASE WHEN a.VehicleClass = 2 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS cust2, SUM(CASE WHEN a.VehicleClass = 3 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS cust3, SUM(CASE WHEN a.VehicleClass = 4 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS cust4, SUM(CASE WHEN a.VehicleClass < 10 AND a.CardType = 26 THEN a.CardNum ELSE 0 END) AS custSubTotal, SUM(CASE WHEN a.VehicleClass = 11 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS truck1, SUM(CASE WHEN a.VehicleClass = 12 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS truck2, SUM(CASE WHEN a.VehicleClass = 13 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS truck3, SUM(CASE WHEN a.VehicleClass = 14 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS truck4, SUM(CASE WHEN a.VehicleClass = 15 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS ruck5, SUM(CASE WHEN a.VehicleClass = 16 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS truck6, SUM(CASE WHEN a.VehicleClass > 10 AND a.VehicleClass < 20 AND a.CardType = 26 THEN a.CardNum ELSE 0 END) AS truckSubTotal, SUM(CASE WHEN a.VehicleClass = 21 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS spec1, SUM(CASE WHEN a.VehicleClass = 22 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS spec2, SUM(CASE WHEN a.VehicleClass = 23 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS spec3, SUM(CASE WHEN a.VehicleClass = 24 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS spec4, SUM(CASE WHEN a.VehicleClass = 25 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS spec5, SUM(CASE WHEN a.VehicleClass = 26 AND a.CardType = 26 THEN a.CardNum ELSE 0 END ) AS spec6, SUM(CASE WHEN a.VehicleClass > 20 AND a.VehicleClass < 30 AND a.CardType != 22 AND a.CardType != 23 THEN a.CardNum ELSE 0 END) AS specSubTotal, SUM(CASE WHEN a.CardType IN(22,23) AND right(a.OperatorID,3) != 971 THEN a.CarNum ELSE 0 END) AS etcNum, SUM(CASE WHEN a.CardType = 254 THEN a.CarNum ELSE 0 END) AS paperNum, SUM(CASE WHEN a.DealStatus&14=8 THEN a.CarNum ELSE 0 END) AS militaryNum, SUM(CASE WHEN a.DealStatus&14=6 THEN a.CarNum ELSE 0 END) AS officialNum, SUM(CASE WHEN a.DealStatus&14=14 THEN a.CarNum ELSE 0 END) AS fleetNum, SUM(CASE WHEN a.DealStatus&14=10 THEN a.CarNum ELSE 0 END) AS preferNum FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
ORDER BY StaDate ASC
ORDER BY monthDate ASC
ORDER BY StationID ASC

SELECT a.ShiftID AS shiftId, a.OperatorID AS operatorId, a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, LEFT(a.StaDate, 6) AS monthDate, a.StaDate AS staDate, IFNULL(SUM(CASE WHEN a.VehicleClass = 1 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS cust1, IFNULL(SUM(CASE WHEN a.VehicleClass = 2 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS cust2, IFNULL(SUM(CASE WHEN a.VehicleClass = 3 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS cust3, IFNULL(SUM(CASE WHEN a.VehicleClass = 4 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS cust4, IFNULL(SUM(CASE WHEN a.VehicleClass < 10 AND a.CardType=26 THEN a.CardNum ELSE 0 END), 0) AS custSubTotal, IFNULL(SUM(CASE WHEN a.VehicleClass = 11 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS truck1, IFNULL(SUM(CASE WHEN a.VehicleClass = 12 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS truck2, IFNULL(SUM(CASE WHEN a.VehicleClass = 13 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS truck3, IFNULL(SUM(CASE WHEN a.VehicleClass = 14 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS truck4, IFNULL(SUM(CASE WHEN a.VehicleClass = 15 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS ruck5, IFNULL(SUM(CASE WHEN a.VehicleClass = 16 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS truck6, IFNULL(SUM(CASE WHEN a.VehicleClass > 10 AND a.VehicleClass < 20 AND a.CardType=26 THEN a.CardNum ELSE 0 END), 0) AS truckSubTotal, IFNULL(SUM(CASE WHEN a.VehicleClass = 21 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS spec1, IFNULL(SUM(CASE WHEN a.VehicleClass = 22 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS spec2, IFNULL(SUM(CASE WHEN a.VehicleClass = 23 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS spec3, IFNULL(SUM(CASE WHEN a.VehicleClass = 24 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS spec4, IFNULL(SUM(CASE WHEN a.VehicleClass = 25 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS spec5, IFNULL(SUM(CASE WHEN a.VehicleClass = 26 AND a.CardType=26 THEN a.CardNum ELSE 0 END ), 0) AS spec6, IFNULL(SUM(CASE WHEN a.VehicleClass > 20 AND a.VehicleClass < 30 AND a.CardType=26 THEN a.CardNum ELSE 0 END), 0) AS specSubTotal, IFNULL(SUM(CASE WHEN a.CardType = 254 THEN a.CarNum ELSE 0 END), 0) AS paperNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=8 AND a.DealStatus&2048 != 2048 THEN a.CarNum ELSE 0 END), 0) AS militaryNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=6 THEN a.CarNum ELSE 0 END), 0) AS officialNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=14 AND a.CardType != 254 THEN a.CarNum ELSE 0 END), 0) AS fleetNum, IFNULL(SUM(CASE WHEN a.DealStatus&14=10 AND a.VehicleStatus IN (1,101) THEN a.CarNum ELSE 0 END), 0) AS preferNum, IFNULL(SUM(CASE WHEN a.DealStatus&32=32 THEN a.CarNum ELSE 0 END),0) AS noneNum, IFNULL(SUM(CASE WHEN a.DealStatus&2048=2048 AND a.CardType in (0,2,26) THEN a.CarNum ELSE 0 END),0) AS badNum, IFNULL(SUM(CASE WHEN a.PayType=2 AND RIGHT(a.OperatorID,3) != 981 THEN a.CarNum ELSE 0 END),0) AS etcNum, IFNULL(SUM(CASE WHEN a.CardType=254 AND a.DealStatus&14 != 14 THEN a.CarNum ELSE 0 END),0) AS paperNum FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
ORDER BY StaDate ASC
ORDER BY monthDate ASC
ORDER BY StationID ASC

SELECT a.StationID AS stationId, (SELECT StationName FROM dbtoms.tbstationinfo WHERE StationID = a.StationID LIMIT 1) AS stationName, IFNULL(SUM(a.InNum), 0) AS txkdr, IFNULL(SUM(a.ReceivedNum), 0) AS cksh, IFNULL(SUM(a.BadRecNUm), 0) AS hksh, IFNULL(SUM(a.RecoverNum), 0) AS txkhf, IFNULL(SUM(a.OutNum), 0) AS txkdc, IFNULL(SUM(a.SendNum), 0) AS rkfk, IFNULL(SUM(a.BadOutNum), 0) AS hksj, IFNULL(SUM(a.AdjustNum), 0) AS kcwhs, IFNULL(SUM(a.InNum+a.ReceivedNum-a.BadRecNUm+a.RecoverNum-a.OutNum-a.SendNum-a.BadOutNum+a.AdjustNum), 0) kcbd, IFNULL(SUM(a.BadStockNum), 0) AS kchk, IFNULL(SUM(a.StockNum), 0) AS kczck FROM ${tableName} a
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate = #{staDate}
GROUP BY StationID ORDER BY StationID

SELECT a.StaDate AS staDate, IFNULL(SUM(a.InNum), 0) AS txkdr, IFNULL(SUM(a.ReceivedNum), 0) AS cksh, IFNULL(SUM(a.BadRecNUm), 0) AS hksh, IFNULL(SUM(a.RecoverNum), 0) AS txkhf, IFNULL(SUM(a.OutNum), 0) AS txkdc, IFNULL(SUM(a.SendNum), 0) AS rkfk, IFNULL(SUM(a.BadOutNum), 0) AS hksj, IFNULL(SUM(a.AdjustNum), 0) AS kcwhs, IFNULL(SUM(a.InNum+a.ReceivedNum-a.BadRecNUm+a.RecoverNum-a.OutNum-a.SendNum-a.BadOutNum+a.AdjustNum), 0) kcbd, IFNULL(SUM(a.BadStockNum), 0) AS kchk, IFNULL(SUM(a.StockNum), 0) AS kczck FROM ${tableName} a
AND CancelFlag = 0 AND StationID in
#{stationId}
AND LEFT(StaDate, 6) = #{staDate}
GROUP BY StaDate ORDER BY StaDate

SELECT StationID AS stationId, StaDate AS staDate, ShiftID AS shiftId, StockNum AS stockNum, SendNum AS sendNum, ReceivedNum AS receivedNum, InNum AS inNum, OutNum AS outNum, RecoverNum AS recoverNum, BadStockNum AS badStockNum, BadRecNum AS badRecNum, BadOutNum AS badOutNum, AdjustNum AS adjustNum, BalanceOP AS balanceOp FROM tbstc
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate = #{staDate}
AND ShiftID = #{shiftId}
ORDER BY BalanceOP ASC

SELECT a.StationID AS stationId, a.StaDate AS staDate, a.ShiftID AS shiftId, a.BalanceOP AS balanceOp, LEFT(a.StaDate, 6) AS monthDate, SUM(a.StockNum) AS stockNum, SUM(a.SendNum) AS sendNum, SUM(a.ReceivedNum) AS receivedNum, SUM(a.InNum) AS inNum, SUM(a.OutNum) AS outNum, SUM(a.RecoverNum) AS recoverNum, SUM(a.BadStockNum) AS badStockNum, SUM(a.BadRecNum) AS badRecNum, SUM(a.BadOutNum) AS badOutNum, SUM(a.AdjustNum) AS adjustNum, SUM(a.BalanceOP) AS balanceOp FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
